use super::*;

/// Normalized edit-distance similarity of two strings: `1 - lev/maxlen`, in `[0,1]`.
pub(crate) fn edit_ratio(a: &str, b: &str) -> f64 {
    let max = a.chars().count().max(b.chars().count());
    if max == 0 {
        return 1.0;
    }
    1.0 - (levenshtein(a, b) as f64 / max as f64)
}
